mapper.select:

where a.del_flag = '0'
and a.title like concat('%', #{title}, '%')
and a.article_type = #{articleType}
and a.status = #{status}
and a.related_plant_id = #{relatedPlantId}
and a.publish_time >= #{params.beginTime}
and a.publish_time <= #{params.endTime}
order by a.sort_order, a.article_id desc
